[<RequireQualifiedAccess>]
type CustomerNotificationsSeverity =
    | Info
    | Success
    | Warning
    | Critical

let customerNotificationsSeverityToString (value: CustomerNotificationsSeverity) : string =
    match value with
    | CustomerNotificationsSeverity.Info -> "info"
    | CustomerNotificationsSeverity.Success -> "success"
    | CustomerNotificationsSeverity.Warning -> "warning"
    | CustomerNotificationsSeverity.Critical -> "critical"

let parseCustomerNotificationsSeverity (value: string) : Result<CustomerNotificationsSeverity, string> =
    match value with
    | "info" -> Ok CustomerNotificationsSeverity.Info
    | "success" -> Ok CustomerNotificationsSeverity.Success
    | "warning" -> Ok CustomerNotificationsSeverity.Warning
    | "critical" -> Ok CustomerNotificationsSeverity.Critical
    | _ -> Error ("unsupported customer_notifications.severity: " + value)

