      CustomerNotificationsBody: string
      CustomerNotificationsLink: string option
      CustomerNotificationsReadAt: string option
      CustomerNotificationsCreatedAt: string
      CustomerNotificationsUpdatedAt: string
      CustomerNotificationsVersion: int64
